{
  "premises": [
    {
      "statement": "The feature-info input contains at most one row per feature_id.",
      "about": "data",
      "target": "marts.feature",
      "evidence_of_dependence": "SELECT f.* ... FROM intermediate.int_pendo__feature_info f LEFT JOIN m USING(feature_id)",
      "alternative": "The feature-info contract says \"duplicates can occur if a joined table has multiple matches for a key\", whereas the feature mart requires \"One row per feature_id\".",
      "importance": 4,
      "reason": "Duplicate feature-info records propagate into the dimension and repeat its usage metrics.",
      "updates": null
    },
    {
      "statement": "Timestamp passthrough takes precedence over the VARCHAR output types declared for timestamp fields in these marts.",
      "about": "requirement",
      "target": "marts.account, marts.visitor, marts.feature, marts.guide, marts.feature_event, marts.guide_event",
      "evidence_of_dependence": "SELECT a.*; SELECT l.*; SELECT f.*; SELECT g.*; SELECT w.*; SELECT e.*",
      "alternative": "These mart contracts declare several timestamp fields as \"data_type: VARCHAR\", while their upstream contracts declare TIMESTAMP; the business logic also describes those fields as passed through unchanged.",
      "importance": 3,
      "reason": "The implementation resolves a contract ambiguity without establishing which output schema is required.",
      "updates": null
    },
    {
      "statement": "DOUBLE sums are acceptable for outputs declared as integer pageview or click totals.",
      "about": "requirement",
      "target": "marts.page.sum_pageviews, marts.visitor_feature.sum_clicks",
      "evidence_of_dependence": "sum(num_events) sum_pageviews; sum(num_events) sum_clicks",
      "alternative": "The page and visitor-feature contracts declare these outputs as BIGINT, while both staging event contracts declare num_events as DOUBLE.",
      "importance": 3,
      "reason": "Without casts, the generated schema differs from the contract and can retain fractional totals.",
      "updates": null
    },
    {
      "statement": "The visitor mart may preserve last_browser_version as VARCHAR rather than produce the declared DOUBLE type.",
      "about": "requirement",
      "target": "marts.visitor.last_browser_version",
      "evidence_of_dependence": "SELECT l.* ... FROM intermediate.int_pendo__latest_visitor l",
      "alternative": "The latest-visitor contract declares last_browser_version as VARCHAR, but the visitor mart declares it as DOUBLE while describing it as pass-through.",
      "importance": 2,
      "reason": "This unresolved type conflict affects the visitor dimension's output schema.",
      "updates": null
    },
    {
      "statement": "The explicitly specified latest-visitor and latest-account left joins may be omitted from the event marts.",
      "about": "requirement",
      "target": "marts.feature_event, marts.guide_event, marts.page_event",
      "evidence_of_dependence": "The generated feature_event, guide_event, and page_event queries join metadata but contain no joins to intermediate.int_pendo__latest_visitor or intermediate.int_pendo__latest_account.",
      "alternative": "Each event contract explicitly requires these LEFT JOINs, and the task requires \"All SQL logic and dependencies\" to follow the YAML configuration strictly.",
      "importance": 2,
      "reason": "Although the latest models select unique keys, omitting mandated joins changes the specified dependency implementation.",
      "updates": null
    }
  ],
